"use strict";
window.BmDashboard = (() => {
  const hourly=[2,1,0,0,0,2,3,6,9,8,7,12,10,6,11,13,9,12,7,0,0,0,0,0];
  const logs=[
    {time:"18:32:08",keyword:"星际穿越",origin:"Byte-Muse",outcome:"complete",label:"全部成功",sources:"2 / 2",count:42,ms:846},
    {time:"18:30:41",keyword:"流浪地球",origin:"Byte-Muse",outcome:"partial",label:"部分成功",sources:"1 / 2",count:18,ms:10012},
    {time:"18:26:15",keyword:"三体",origin:"手动测试",outcome:"complete",label:"全部成功",sources:"2 / 2",count:26,ms:712},
    {time:"18:22:37",keyword:"Interstellar",origin:"Byte-Muse",outcome:"complete",label:"全部成功",sources:"2 / 2",count:38,ms:632},
    {time:"18:18:02",keyword:"沙丘",origin:"Byte-Muse",outcome:"failed",label:"全部失败",sources:"0 / 2",count:0,ms:10018},
    {time:"18:14:51",keyword:"阿凡达",origin:"Byte-Muse",outcome:"complete",label:"全部成功",sources:"2 / 2",count:19,ms:728},
  ];
  function render(state,current,{h,icon,btn,status}) {
    const week=state.range==="week";
    const d=week?{requests:"864",complete:816,partial:36,failed:12,rate:"94.4%",latency:"0.92",raw:"12,480",unique:"9,730",duplicate:"2,750"}:{requests:"128",complete:120,partial:6,failed:2,rate:"93.8%",latency:"0.86",raw:"1,840",unique:"1,428",duplicate:"412"};
    const rangeText=week?"10月31日—11月6日":"2026年11月6日 · 今天";
    const heading=`<div class="dashboard-heading"><div><h1>${["运行概览","聚合运行台","运行概览"][current]}</h1><p>${["两条连接，每次搜索都有迹可循。","从请求到上游，问题发生在哪里一目了然。","看看今天的搜索，以及正在为你工作的连接。"][current]}</p></div><div class="dashboard-tools"><div class="segmented" aria-label="统计范围"><button data-action="range" data-id="today" class="${!week?"active":""}" aria-pressed="${!week}">今天</button><button data-action="range" data-id="week" class="${week?"active":""}" aria-pressed="${week}">最近 7 天</button></div>${btn("搜索并测试","goto-search","",true,"search")}</div></div>`;
    const outcome=`<div class="outcome-bar" aria-label="请求结果构成：全部成功 ${d.complete} 次，部分成功 ${d.partial} 次，全部失败 ${d.failed} 次"><i style="flex:${d.complete}" class="complete"></i><i style="flex:${d.partial}" class="partial"></i><i style="flex:${d.failed}" class="failed"></i></div><div class="outcome-legend"><span><i class="complete"></i>全部成功 <b>${d.complete}</b></span><span><i class="partial"></i>部分成功 <b>${d.partial}</b></span><span><i class="failed"></i>全部失败 <b>${d.failed}</b></span></div>`;
    const metrics=`<section class="metrics-band" aria-label="运行指标"><div class="stat"><span>搜索请求</span><strong>${d.requests}<small>次</small></strong><p>${week?"最近 7 天":"今天"} · 业务与手动测试</p></div><div class="stat"><span>完整成功率</span><strong>${d.rate}</strong><p>全部目标源均响应成功</p></div><div class="stat"><span>平均聚合耗时</span><strong>${d.latency}<small>秒</small></strong><p>P95 · ${week?"2.61":"2.40"} 秒</p></div><div class="stat"><span>去重后结果</span><strong>${d.unique}<small>条</small></strong><p>合并 ${d.duplicate} 条重复结果</p></div></section>`;
    const sourceMarkup=state.sources.slice(0,2).map(s=>`<article class="overview-source"><div class="os-top"><span class="source-emblem">${icon(s.id==="xiuxian"?"plug":"source")}</span><div class="os-title"><h3>${h(s.name)}</h3><p>${s.id==="xiuxian"?"家庭局域网 · Tailscale":s.id==="avdb"?"OVH · Docker 内网":"扩展源 · 示例"}</p></div>${status(s)}</div><div class="os-stats"><div><span>最近响应</span><b>${s.status==="unknown"?"—":s.ms+" ms"}</b></div><div><span>最近结果</span><b>${s.status==="unknown"?"—":s.count+" 条"}</b></div><button class="icon-btn" data-action="source-detail" data-id="${h(s.id)}" aria-label="查看 ${h(s.name)} 诊断">${icon("arrow")}</button></div><div class="source-history" aria-label="样例：最近请求状态">${Array.from({length:30},(_,i)=>`<i class="${s.id==="xiuxian"&&[7,18,22].includes(i)?"partial":"complete"}" title="样例请求 ${i+1}"></i>`).join("")}</div><div class="os-footer"><span>最近样例请求 ${state.lastTime}</span><button data-action="edit" data-id="${h(s.id)}">编辑配置</button></div></article>`).join("");
    const sources=`<section class="sources-overview"><div class="dashboard-section-heading"><h2>上游数据源 <span>${state.sources.length}</span></h2><button data-route="sources">管理数据源 ${icon("arrow")}</button></div><div class="overview-sources-grid">${sourceMarkup}</div>${state.sources.length>2?`<button class="additional-sources" data-route="sources">另有 ${state.sources.length-2} 个源，查看全部 ${icon("arrow")}</button>`:""}<p class="source-caption">状态来自最近一次样例请求，不代表持续在线。</p></section>`;
    const values=week?[58,81,132,118,147,200,128]:hourly;
    const metric=state.metric||"requests";
    const scale=metric==="latency"?3:Math.max(...values);
    const bars=values.map((n,i)=>{const value=metric==="latency"?(n===0?0:0.3+(i%6)*.32):n;return `<div class="chart-column"><div class="chart-bar${i===values.length-1?" last":""}" style="height:${Math.max(n?4:0,value/scale*100)}%" title="${week?["10/31","11/01","11/02","11/03","11/04","11/05","11/06"][i]:String(i).padStart(2,"0")+":00"} · ${value}${metric==="latency"?" 秒":" 次"}"></div></div>`;}).join("");
    const trend=`<section class="trend-section"><div class="dashboard-section-heading"><div><h2>${metric==="latency"?"聚合耗时":"请求趋势"}</h2><p>${rangeText} · ${week?"按天":"按小时"}统计</p></div><div class="segmented small-segment" aria-label="图表指标"><button data-action="metric" data-id="requests" class="${metric==="requests"?"active":""}">请求数</button><button data-action="metric" data-id="latency" class="${metric==="latency"?"active":""}">耗时</button></div></div><div class="chart-shell"><div class="y-axis"><span>${metric==="latency"?"3 s":week?"200":"15"}</span><span>${metric==="latency"?"1.5":week?"100":"8"}</span><span>0</span></div><div class="chart-field"><div class="chart-grid"><i></i><i></i><i></i></div><div class="chart-bars">${bars}</div></div></div><div class="x-axis">${(week?["10/31","11/01","11/02","11/03","11/04","11/05","11/06"]:["00:00","06:00","12:00","18:00","23:00"]).map(t=>`<span>${t}</span>`).join("")}</div><div class="chart-caption"><span><i></i>${metric==="latency"?"平均聚合耗时":"聚合搜索请求"}</span><span>示例数据 · ${week?"7 天":"今天"}</span></div></section>`;
    const filtered=state.onlyErrors?logs.filter(l=>l.outcome!=="complete"):logs;
    const recent=`<section class="recent-requests"><div class="dashboard-section-heading"><div><h2>最近请求</h2><p>每次聚合都能追溯到上游响应</p></div><button class="log-filter${state.onlyErrors?" selected":""}" data-action="log-filter" aria-pressed="${Boolean(state.onlyErrors)}">${icon("settings")}${state.onlyErrors?"显示全部":"只看异常"}</button></div><div class="request-table"><div class="request-table-head"><span>时间</span><span>关键词 / 来源</span><span>聚合状态</span><span>成功源</span><span>结果</span><span>总耗时</span></div>${filtered.slice(0,state.showAll?6:4).map((l,i)=>`<button class="request-line" data-action="log-detail" data-id="${logs.indexOf(l)}"><time>${l.time}</time><span><b>${h(l.keyword)}</b><small>${l.origin}</small></span><span class="outcome-label ${l.outcome}"><i></i>${l.label}</span><span class="mono">${l.sources}</span><span class="mono">${l.count} 条</span><span class="mono">${l.ms>=1000?(l.ms/1000).toFixed(2)+" s":l.ms+" ms"}</span></button>`).join("")}</div><button class="more-requests" data-action="more-logs">${state.showAll?"收起请求":"展开更多请求"} ${icon("arrow")}</button></section>`;
    const summary=`<section class="outcome-summary"><div class="dashboard-section-heading"><h2>请求结果构成</h2><span class="small muted">${d.requests} 次</span></div>${outcome}<p class="outcome-note">部分上游失败，聚合仍可能返回结果。</p></section>`;
    const incident=`<div class="incident-strip">${icon("issue")}<div><strong>18:30 修仙请求超时</strong><p>AVDB 已返回 18 条结果，该次标记为部分成功。</p></div><button data-action="log-detail" data-id="1">查看详情 ${icon("arrow")}</button></div>`;
    return `<div class="dashboard dashboard-${current+1}">${heading}${current===0?`${metrics}<div class="dashboard-primary">${trend}<div class="overview-right">${summary}<div class="quick-test"><h2>确认连接是否正常</h2><p>使用关键词发起一次测试，检查两个源的实际响应。</p>${btn(state.testing?"样例测试中…":"测试启用源","test","",false,"play")}</div></div></div>${sources}${recent}`:current===1?`${metrics}${incident}<div class="dashboard-primary">${trend}${summary}</div><div class="dashboard-secondary">${recent}${sources}</div>`:`${sources}${metrics}<div class="dashboard-primary">${trend}<div class="overview-right">${summary}<div class="dedup-summary"><h2>聚合与去重</h2><dl><div><dt>源返回结果</dt><dd>${d.raw}</dd></div><div><dt>重复合并</dt><dd>− ${d.duplicate}</dd></div><div><dt>最终返回</dt><dd>${d.unique}</dd></div></dl><p>按 BTIH、ED2K 或标题合并</p></div></div></div>${recent}`}<div class="dashboard-end"><span>BM-BT-Proxy · 运行概览设计预览</span><span>统计待后端采集 · 目前展示样例</span></div></div>`;
  }
  return {render,logs};
})();
